insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','Both use a knee-dominant squat pattern involving the legs and hips.','The goblet variation adds external resistance in front of the body; the bodyweight variation needs no weights.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','Both use a knee-dominant squat pattern involving the legs and hips.','The goblet variation adds external resistance in front of the body; the bodyweight variation needs no weights.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000004','Both use a hip-hinge pattern involving the hamstrings and glutes.','Dumbbells allow separate hand positions and use per-implement loads; a barbell uses a shared bar and total load.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000004','20000000-0000-4000-8000-000000000003','Both use a hip-hinge pattern involving the hamstrings and glutes.','Dumbbells allow separate hand positions and use per-implement loads; a barbell uses a shared bar and total load.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000005','20000000-0000-4000-8000-000000000006','Both use horizontal pushing with chest, triceps, and shoulder involvement.','Dumbbells require independent control; the machine supports a guided movement path. Loads are not interchangeable.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000006','20000000-0000-4000-8000-000000000005','Both use horizontal pushing with chest, triceps, and shoulder involvement.','Dumbbells require independent control; the machine supports a guided movement path. Loads are not interchangeable.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000007','20000000-0000-4000-8000-000000000008','Both use horizontal pulling with back and biceps involvement.','The supported dumbbell row is unilateral; the seeded machine row is bilateral with a guided setup. Record reps consistently.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000008','20000000-0000-4000-8000-000000000007','Both use horizontal pulling with back and biceps involvement.','The supported dumbbell row is unilateral; the seeded machine row is bilateral with a guided setup. Record reps consistently.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000009','20000000-0000-4000-8000-000000000010','Both use overhead pressing with shoulder and triceps involvement.','Dumbbells require independent stabilization; the machine guides the movement. Seat and machine design affect the setup.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
