insert into public.exercise_alternatives(exercise_id,alternative_exercise_id,similarities,differences,suitability_notes) values ('20000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000012','Both practice trunk control while moving limbs.','Dead bugs are performed lying on the back; bird dogs use hands-and-knees support. They have different balance and support demands.','Use only equipment you have and movements you can perform comfortably. Start a separate load history for this variation; seek qualified guidance for pain or medical limitations.');
